int is_valid_column(const char *s) {
    static const char *valid[] = {
        "PID","Command","STATE","PPID","PGRP","SESSION","TTY","TPGID","MINFLT","CMINFLT","MAJFLT","CMAJFLT","UTIME","STIME","CUTIME","CSTIME","PRIORITY","NICE","STARTTIME","PROCESSOR","M_VIRT","M_RESIDENT","M_SHARE","M_TRS","M_DRS","M_LRS","ST_UID","PERCENT_CPU","PERCENT_MEM","USER","TIME","NLWP","TGID","PERCENT_NORM_CPU","ELAPSED","SCHEDULERPOLICY","RCHAR","WCHAR","SYSCR","SYSCW","RBYTES","WBYTES","CNCLWB","IO_READ_RATE","IO_WRITE_RATE","IO_RATE","CGROUP","OOM","IO_PRIORITY","M_PSS","M_SWAP","M_PSSWP","CTXT","SECATTR","COMM","EXE","CWD","AUTOGROUP_ID","AUTOGROUP_NICE","CCGROUP","CONTAINER","M_PRIV","GPU_TIME","GPU_PERCENT","ISCONTAINER", NULL
    };
    for (int i=0; valid[i]; i++) if (strcmp(s, valid[i])==0) return 1;
    return 0;
}

int validate_delay(const char *s) {
    if (!s || s[0]=='\0') return 0;
    const char *p = s;
    while (isspace((unsigned char)*p)) p++;
    if (*p=='+'||*p=='-') p++;
    if (!isdigit((unsigned char)*p)) return 0;
    return 1;
}
int validate_highlight(const char *s) {
    return validate_delay(s);
}
int validate_filter(const char *s) {
    if (!s || s[0]=='\0') return 0;
    if (s[0]=='|') return 0;
    return 1;
}
int validate_user(const char *s) {
    if (!s || s[0]=='\0') return 0;
    const char *p = s;
    while (isspace((unsigned char)*p)) p++;
    const char *num_start = p;
    if (*p=='-') return 0;
    if (*p=='+') p++;
    if (isdigit((unsigned char)*p)) {
        // numeric path, must be all digits until end
        while (isdigit((unsigned char)*p)) p++;
        if (*p!='\0') return 0;
        // range check
        char *end;
        errno=0;
        unsigned long long v = strtoull(num_start, &end, 10);
        if (v > 4294967294ULL) return 0;
        // also need to check errno?
        return 1;
    } else {
        // name path: must not contain whitespace
        for (const char *q=s; *q; q++) if (isspace((unsigned char)*q)) return 0;
        struct passwd *pw = getpwnam(s);
        if (!pw) return 0;
        return 1;
    }
