int main(int argc, char *argv[]) {
    static struct option long_options[] = {
        {"no-color", no_argument, 0, 'C'},
        {"no-colour", no_argument, 0, 'C'},
        {"delay", required_argument, 0, 'd'},
        {"filter", required_argument, 0, 'F'},
        {"no-function-bar", no_argument, 0, 1000},
        {"help", no_argument, 0, 'h'},
        {"highlight-changes", optional_argument, 0, 'H'},
        {"no-mouse", no_argument, 0, 'M'},
        {"no-meters", no_argument, 0, 1001},
        {"max-iterations", required_argument, 0, 'n'},
        {"pid", required_argument, 0, 'p'},
        {"readonly", no_argument, 0, 1002},
        {"sort-key", required_argument, 0, 's'},
        {"tree", no_argument, 0, 't'},
        {"user", optional_argument, 0, 'u'},
        {"no-unicode", no_argument, 0, 'U'},
        {"version", no_argument, 0, 'V'},
        {0,0,0,0}
    };

    opterr = 1;
    int opt;
    int option_index = 0;
    // Note: we need to handle optional args manually for -H and -u
    while ((opt = getopt_long(argc, argv, "Cd:F:hH::Mn:p:s:tUu::V", long_options, &option_index)) != -1) {
        switch (opt) {
            case 'C':
