                if (!validate_delay(val)) {
                    fprintf(stderr, "Error: invalid delay value \"%s\".\n", val);
                    return 1;
                }
                break;
            }
            case 'F': {
                const char *val = optarg;
                if (!validate_filter(val)) {
                    fprintf(stderr, "Error: invalid filter value \"%s\".\n", val);
                    return 1;
                }
                break;
            }
            case 'h':
                fputs(help_text, stdout);
                return 0;
            case 'H': {
                const char *val = optarg;
                // Manual handling for optional arg when getopt didn't consume
                if (!val && optind < argc && argv[optind][0] != '-' && argv[optind][0] != '\0') {
                    // Check if next arg should be taken as highlight value
                    // For highlight, any next arg not starting with '-' and not empty should be taken
                    // But need to ensure we don't consume something that is intended as non-option? However htop's behavior for optional is to take next token if it doesn't look like option.
                    // So we take it.
                    val = argv[optind];
                    optind++;
                }
                if (val) {
                    if (!validate_highlight(val)) {
                        fprintf(stderr, "Error: invalid highlight delay value \"%s\".\n", val);
                        return 1;
                    }
                }
                break;
            }
            case 'M':
