            case 'n': {
                const char *val = optarg;
                // Need to differentiate invalid vs must be positive
                const char *p = val;
                while (isspace((unsigned char)*p)) p++;
                const char *after = p;
                if (*p=='+'||*p=='-') p++;
                if (!isdigit((unsigned char)*p)) {
                    fprintf(stderr, "Error: invalid maximum iteration count \"%s\".\n", val);
                    return 1;
                }
                char *end;
                long v = strtol(val, &end, 10);
                if (v <= 0) {
                    fprintf(stderr, "Error: maximum iteration count must be positive.\n");
                    return 1;
                }
                break;
            }
            case 'p': {
                // No validation, accept any
                break;
            }
            case 's': {
                const char *val = optarg;
                if (strcmp(val, "help")==0) {
                    fputs(sort_help, stdout);
                    return 0;
                }
                if (!is_valid_column(val)) {
                    fprintf(stderr, "Error: invalid column \"%s\".\n", val);
                    return 1;
                }
                break;
            }
            case 't':
                break;
            case 'u': {
                const char *val = optarg;
                if (!val && optind < argc && argv[optind][0] != '-' && argv[optind][0] != '\0') {
                    val = argv[optind];
                    optind++;
                }
                if (val) {
                    if (!validate_user(val)) {
                        fprintf(stderr, "Error: invalid user \"%s\".\n", val);
                        return 1;
                    }
                }
                break;
            }
            case 'U':
