            case '?':
                return 1;
            default:
                return 1;
        }
    }

    if (optind < argc) {
        fprintf(stderr, "Error: unsupported non-option ARGV-elements:");
        for (int i=optind; i<argc; i++) {
            fprintf(stderr, " %s", argv[i]);
        }
        fprintf(stderr, "\n");
        return 1;
    }

    // Terminal check
    const char *term = getenv("TERM");
    const char *print_term = (term && term[0]!='\0') ? term : "unknown";
    if (!term || term[0]=='\0') {
        fprintf(stderr, "Error opening terminal: unknown.\n");
        return 1;
    }
    int err;
    if (setupterm(NULL, STDOUT_FILENO, &err) != OK) {
        fprintf(stderr, "Error opening terminal: %s.\n", print_term);
        return 1;
    }

    // Success path: for now just exit 0
    return 0;
}
