                    // For highlight, any next arg not starting with '-' and not empty should be taken
                    // But need to ensure we don't consume something that is intended as non-option? However htop's behavior for optional is to take next token if it doesn't look like option.
                    // So we take it.
                    val = argv[optind];
                    optind++;
                }
                if (val) {
                    if (!validate_highlight(val)) {
                        fprintf(stderr, "Error: invalid highlight delay value \"%s\".\n", val);
